{
  description = "The purely functional package manager";

  inputs.nixpkgs.url = "https://channels.nixos.org/nixos-26.05/nixexprs.tar.xz";

  inputs.nixpkgs-regression.url = "github:NixOS/nixpkgs/215d4d0fd80ca5163643b03a33fde804a29cc1e2";
  inputs.nixpkgs-23-11.url = "github:NixOS/nixpkgs/a62e6edd6d5e1fa0329b8653c801147986f8d446";
  inputs.flake-compat = {
    url = "github:NixOS/flake-compat";
    flake = false;
  };

  # dev tooling
  inputs.flake-parts.url = "github:hercules-ci/flake-parts";
  inputs.git-hooks-nix.url = "github:cachix/git-hooks.nix";
  # work around https://github.com/NixOS/nix/issues/7730
  inputs.flake-parts.inputs.nixpkgs-lib.follows = "nixpkgs";
  inputs.git-hooks-nix.inputs.nixpkgs.follows = "nixpkgs";
  # work around 7730 and https://github.com/NixOS/nix/issues/7807
  inputs.git-hooks-nix.inputs.flake-compat.follows = "";

  outputs =
    inputs@{
      self,
      nixpkgs,
      nixpkgs-regression,
      ...
    }:

    let
      inherit (nixpkgs) lib;

      officialRelease = false;

      linux32BitSystems = [ "i686-linux" ];
      linux64BitSystems = [
        "x86_64-linux"
        "aarch64-linux"
      ];
      linuxSystems = linux32BitSystems ++ linux64BitSystems;
      darwinSystems = [
        "aarch64-darwin"
      ];
      systems = linuxSystems ++ darwinSystems;

      crossSystems = [
        "armv6l-unknown-linux-gnueabihf"
        "armv7l-unknown-linux-gnueabihf"
        "powerpc64-unknown-linux-gnuabielfv1"
        "powerpc64le-unknown-linux-gnu"
        "riscv64-unknown-linux-gnu"
        # Disabled because of https://github.com/NixOS/nixpkgs/issues/344423
        # "x86_64-unknown-netbsd"
        "x86_64-unknown-freebsd"
        "x86_64-w64-mingw32"
      ];

      stdenvs = [
        "ccacheStdenv"
        "clangStdenv"
        "gccStdenv"
        "libcxxStdenv"
        "stdenv"
      ];

      /**
        `flatMapAttrs attrs f` applies `f` to each attribute in `attrs` and
        merges the results into a single attribute set.

        This can be nested to form a build matrix where all the attributes
        generated by the innermost `f` are returned as is.
        (Provided that the names are unique.)

        See https://nixos.org/manual/nixpkgs/stable/index.html#function-library-lib.attrsets.concatMapAttrs
      */
      flatMapAttrs = attrs: f: lib.concatMapAttrs f attrs;

      forAllSystems = lib.genAttrs systems;

      forAllCrossSystems = lib.genAttrs crossSystems;

      forAllStdenvs = lib.genAttrs stdenvs;

      # We don't apply flake-parts to the whole flake so that non-development attributes
      # load without fetching any development inputs.
      devFlake = inputs.flake-parts.lib.mkFlake { inherit inputs; } {
        imports = [ ./maintainers/flake-module.nix ];
        systems = lib.subtractLists crossSystems systems;
        perSystem =
          { system, ... }:
          {
            _module.args.pkgs = nixpkgsFor.${system}.native;
          };
      };

      /**
        Memoized nixpkgs for different platforms for efficiency.
      */
      nixpkgsFor = forAllSystems (
        system:
        let
          makePkgs =
            crossSystem:
            import nixpkgs {
              localSystem = {
                inherit system;
              };
              crossSystem =
                if crossSystem == null then
                  null
                else
                  {
                    config = crossSystem;
                  }
                  // lib.optionalAttrs (crossSystem == "x86_64-w64-mingw32") {
                    emulator = pkgs: "${pkgs.buildPackages.wineWow64Packages.stable}/bin/wine";
                  };
            };
        in
        {
          native = makePkgs null;
          cross = forAllCrossSystems makePkgs;
        }
      );

      /**
        Memoised nix component scopes for different platforms and stdenvs.
      */
      nixComponentsFor = forAllSystems (
        system:
        let
          pkgs = nixpkgsFor.${system}.native;
          makePackageSet =
            pkgs: stdenv:
            (packageSetsFor {
              inherit pkgs;
              getStdenv = pkgs: pkgs.${stdenv};
            }).nixComponents
            // {
              # This is not the nixpkgs fixpoint, but just for easier plubming in hydraJobs and such.
              # Technically you can extract the fixpoint with `callPackage {pkgs}: pkgs`, but that's
              # a little too verbose. And in hydraJobs and flake output definitions no overriding should
              # happen anyway.
              _pkgs = pkgs;
            };
        in
        rec {
          nativeForStdenv = forAllStdenvs (stdenv: makePackageSet pkgs stdenv);
          nativeStaticForStdenv = forAllStdenvs (
            stdenv: makePackageSet nixpkgsFor.${system}.native.pkgsStatic stdenv
          );
          nativeLLVMForStdenv = forAllStdenvs (
            stdenv: makePackageSet nixpkgsFor.${system}.native.pkgsLLVM stdenv
          );
          native = nativeForStdenv.stdenv;
          cross = forAllCrossSystems (
            crossSystem: makePackageSet nixpkgsFor.${system}.cross.${crossSystem} "stdenv"
          );
          nativeStatic = nativeStaticForStdenv.stdenv;
          nativeLLVM = nativeLLVMForStdenv.stdenv;
        }
      );

      /**
        Produce the `nixComponents` and `nixDependencies` package sets (scopes) for
        a given `pkgs` and `getStdenv`.
      */
      packageSetsFor =
        (import ./packaging/scopes.nix {
          inherit officialRelease lib;
          src = self;
        }).packageSetsFor;
    in
    {
      /**
        A Nixpkgs overlay that sets `nix` to something like `packages.<system>.nix-everything`,
        except dependencies aren't taken from (flake) `nix.inputs.nixpkgs`, but from the Nixpkgs packages
        where the overlay is used.
      */
      overlays.default =
        final: prev:
        let
          packageSets = packageSetsFor { pkgs = final; };
        in
        {
          nix = packageSets.nixComponents.nix-everything;
        };

      hydraJobs = import ./packaging/hydra.nix {
        inherit
          inputs
          forAllCrossSystems
          forAllSystems
          lib
          linux64BitSystems
          nixpkgsFor
          nixComponentsFor
          self
          ;
      };

      checks = forAllSystems (
        system:
        (import ./ci/gha/tests {
          inherit system;
          pkgs = nixpkgsFor.${system}.native;
          nixFlake = self;
        }).topLevel
        // (lib.optionalAttrs (builtins.elem system linux64BitSystems)) {
          dockerImage = self.hydraJobs.dockerImage.${system};
        }
        // (lib.optionalAttrs (system == "x86_64-linux")) {
          fuzzing-engine = nixpkgsFor.${system}.native.callPackage ./tests/fuzzing-engine { };
        }
        # Add "passthru" tests
        //
          flatMapAttrs
            {
              "" = {
                pkgs = nixpkgsFor.${system}.native;
              };
            }
            (
              nixpkgsPrefix: args:
              (import ./ci/gha/tests (
                args
                // {
                  nixFlake = self;
                  componentTestsPrefix = nixpkgsPrefix;
                }
              )).componentTests
            )
        // devFlake.checks.${system} or { }
      );

      packages = forAllSystems (
        system:
        {
          # Here we put attributes that map 1:1 into packages.<system>, ie
          # for which we don't apply the full build matrix such as cross or static.
          inherit (nixpkgsFor.${system}.native)
            changelog-d
            ;
          installerScriptForGHA = self.hydraJobs.installerScriptForGHA.${system};
          binaryTarball = self.hydraJobs.binaryTarball.${system};
          # TODO probably should be `nix-cli`
          nix = nixComponentsFor.${system}.native.nix-everything;
          default = nixComponentsFor.${system}.native.nix-everything;
          inherit (nixComponentsFor.${system}.native)
            nix-manual
            nix-manual-manpages-only
            nix-internal-api-docs
            nix-external-api-docs
            ;
        }
        # We need to flatten recursive attribute sets of derivations to pass `flake check`.
        //
          flatMapAttrs
            {
              # Components we'll iterate over in the upcoming lambda
              "nix-util" = { };
              "nix-util-c" = { };
              "nix-util-test-support" = { };
              "nix-util-tests" = { };

              "nix-store" = { };
              "nix-store-c" = { };
              "nix-store-test-support" = { };
              "nix-store-tests" = { };

              "nix-fetchers" = { };
              "nix-fetchers-c" = { };
              "nix-fetchers-tests" = { };

              "nix-expr" = { };
              "nix-expr-c" = { };
              "nix-expr-test-support" = { };
              "nix-expr-tests" = { };

              "nix-flake" = { };
              "nix-flake-c" = { };
              "nix-flake-tests" = { };

              "nix-main" = { };
              "nix-main-c" = { };

              "nix-cmd" = { };

              "nix-nswrapper" = {
                linuxOnly = true;
              };

              "nix-cli" = { };

              "nix-everything" = { };

              "nix-functional-tests" = {
                supportsCross = false;
              };

              "nix-json-schema-checks" = {
                supportsCross = false;
              };

              "nix-clang-tidy-plugin" = {
                supportsCross = false;
              };
            }
            (
              pkgName:
              {
                supportsCross ? true,
                linuxOnly ? false,
              }:
              lib.optionalAttrs (linuxOnly -> nixpkgsFor.${system}.native.stdenv.hostPlatform.isLinux) (
                {
                  # These attributes go right into `packages.<system>`.
                  "${pkgName}" = nixComponentsFor.${system}.native.${pkgName};
                  "${pkgName}-static" = nixComponentsFor.${system}.nativeStatic.${pkgName};
                  # FIXME: These don't actually evaluate on darwin.
                  "${pkgName}-llvm" = nixComponentsFor.${system}.nativeLLVM.${pkgName};
                }
                // flatMapAttrs (lib.genAttrs stdenvs (_: { })) (
                  stdenvName:
                  { }:
                  {
                    # These attributes go right into `packages.<system>`.
                    "${pkgName}-${stdenvName}" = nixComponentsFor.${system}.nativeForStdenv.${stdenvName}.${pkgName};
                  }
                )
              )
              // lib.optionalAttrs supportsCross (
                flatMapAttrs (lib.genAttrs crossSystems (_: { })) (
                  crossSystem:
                  { }:
                  lib.optionalAttrs
                    (linuxOnly -> nixpkgsFor.${system}.cross.${crossSystem}.stdenv.hostPlatform.isLinux)
                    {
                      # These attributes go right into `packages.<system>`.
                      "${pkgName}-${crossSystem}" = nixComponentsFor.${system}.cross.${crossSystem}.${pkgName};
                    }
                )
              )
            )
        // lib.optionalAttrs (self.hydraJobs.rustInstaller ? ${system}) {
          rustInstaller = self.hydraJobs.rustInstaller.${system};
        }
        // lib.optionalAttrs (self.hydraJobs.dockerImage ? ${system}) {
          dockerImage = self.hydraJobs.dockerImage.${system};
        }
      );

      apps = forAllSystems (
        system:
        let
          pkgs = nixpkgsFor.${system}.native;
          opener = if pkgs.stdenv.isDarwin then "open" else "xdg-open";
        in
        {
          open-manual = {
            type = "app";
            program = "${pkgs.writeShellScript "open-nix-manual" ''
              path="${self.packages.${system}.nix-manual.site}/index.html"
              if ! ${opener} "$path"; then
                echo "Failed to open manual with ${opener}. Manual is located at:"
                echo "$path"
              fi
            ''}";
            meta.description = "Open the Nix manual in your browser";
          };
        }
      );

      devShells =
        let
          makeShell = import ./packaging/dev-shell.nix { inherit lib devFlake; };
          makeShell' =
            components:
            makeShell {
              pkgs = components._pkgs;
              nixComponents = components.overrideScope (
                finalScope: prevScope: {
                  withUnityBuild = false;
                }
              );
            };
          prefixAttrs = prefix: lib.concatMapAttrs (k: v: { "${prefix}-${k}" = v; });
        in
        forAllSystems (
          system:
          prefixAttrs "native" (
            forAllStdenvs (stdenvName: makeShell' nixComponentsFor.${system}.nativeForStdenv.${stdenvName})
          )
          // lib.optionalAttrs (!nixpkgsFor.${system}.native.stdenv.isDarwin) (
            prefixAttrs "static" (
              forAllStdenvs (
                stdenvName: makeShell' nixComponentsFor.${system}.nativeStaticForStdenv.${stdenvName}
              )
            )
            // prefixAttrs "llvm" (
              forAllStdenvs (stdenvName: makeShell' nixComponentsFor.${system}.nativeLLVMForStdenv.${stdenvName})
            )
            // prefixAttrs "cross" (
              forAllCrossSystems (crossSystem: makeShell' nixComponentsFor.${system}.cross.${crossSystem})
            )
          )
          // {
            native = self.devShells.${system}.native-stdenv;
            default = self.devShells.${system}.native;
          }
        );

      lib = {
        /**
          Creates a package set for a given Nixpkgs instance and stdenv.

          # Inputs

          - `pkgs`: The Nixpkgs instance to use.

          - `getStdenv`: _Optional_ A function that takes a package set and returns the stdenv to use.
            This needs to be a function in order to support cross compilation - the `pkgs` passed to `getStdenv` can be `pkgsBuildHost` or any other variation needed.

          # Outputs

          The return value is a fresh Nixpkgs scope containing all the packages that are defined in the Nix repository,
          as well as some internals and parameters, which may be subject to change.

          # Example

          ```console
          nix repl> :lf NixOS/nix
          nix-repl> ps = lib.makeComponents { pkgs = import inputs.nixpkgs { crossSystem = "riscv64-linux"; }; }
          nix-repl> ps
          {
            appendPatches = «lambda appendPatches @ ...»;
            callPackage = «lambda callPackageWith @ ...»;
            overrideAllMesonComponents = «lambda overrideSource @ ...»;
            overrideSource = «lambda overrideSource @ ...»;
            # ...
            nix-everything
            # ...
            nix-store
            nix-store-c
            # ...
          }
          ```
        */
        makeComponents =
          {
            pkgs,
            getStdenv ? pkgs: pkgs.stdenv,
          }:

          let
            packageSets = packageSetsFor { inherit getStdenv pkgs; };
          in
          packageSets.nixComponents;
      };
    };
}

{
  lib,
  officialRelease,
  src,
}:
rec {
  packageSetsFor =
    args@{
      pkgs,
      getStdenv ? pkgs: pkgs.stdenv,
    }:
    let
      nixComponentsSplices = lib.mapCrossIndex (
        pkgs': (packageSetsFor (args // { pkgs = pkgs'; })).nixComponents
      ) (lib.renameCrossIndexFrom "pkgs" pkgs);
      nixDependenciesSplices = lib.mapCrossIndex (
        pkgs': (packageSetsFor (args // { pkgs = pkgs'; })).nixDependencies
      ) (lib.renameCrossIndexFrom "pkgs" pkgs);

      # A new scope, so that we can use `callPackage` to inject our own interdependencies
      # without "polluting" the top level "`pkgs`" attrset.
      # This also has the benefit of providing us with a distinct set of packages
      # we can iterate over.
      nixComponents =
        lib.makeScopeWithSplicing'
          {
            inherit (pkgs) splicePackages;
            inherit (nixDependencies) newScope;
          }
          {
            otherSplices = lib.renameCrossIndexTo "self" nixComponentsSplices;
            f = import ./components.nix {
              inherit (pkgs) lib;
              inherit officialRelease;
              inherit pkgs;
              inherit src;
              maintainers = [ ];
            };
          };

      # The dependencies are in their own scope, so that they don't have to be
      # in Nixpkgs top level `pkgs` or `nixComponents`.
      nixDependencies =
        lib.makeScopeWithSplicing'
          {
            inherit (pkgs) splicePackages;
            inherit (pkgs) newScope; # layered directly on pkgs, unlike nixComponents above
          }
          {
            otherSplices = lib.renameCrossIndexTo "self" nixDependenciesSplices;
            f = import ./dependencies.nix {
              inherit pkgs;
              stdenv = getStdenv pkgs;
            };
          };

      # If the package set is largely empty, we should(?) return empty sets
      # This is what most package sets in Nixpkgs do. Otherwise, we get
      # an error message that indicates that some stdenv attribute is missing,
      # and indeed it will be missing, as seemingly `pkgsTargetTarget` is
      # very incomplete.
      fixup = lib.mapAttrs (k: v: if !(pkgs ? newScope) then { } else v);
    in
    fixup {
      inherit nixDependencies;
      inherit nixComponents;
    };
}

{
  lib,
  pkgs,
  src,
  officialRelease,
  maintainers,
}:

scope:

let
  inherit (scope)
    callPackage
    ;
  inherit
    (scope.callPackage (
      { stdenv }:
      {
        inherit stdenv;
      }
    ) { })
    stdenv
    ;
  inherit (pkgs.buildPackages)
    meson
    ninja
    pkg-config
    ;

  baseVersion = lib.fileContents ../.version;

  versionSuffix = lib.optionalString (!officialRelease) "pre";

  fineVersionSuffix =
    lib.optionalString (!officialRelease)
      "pre${
        builtins.substring 0 8 (src.lastModifiedDate or src.lastModified or "19700101")
      }_${src.shortRev or "dirty"}";

  fineVersion = baseVersion + fineVersionSuffix;

  root = ../.;

  # Indirection for Nixpkgs to override when package.nix files are vendored
  filesetToSource = lib.fileset.toSource;

  /**
    Given a stdenv and set of layers, create a mkDerivation-like function
  */
  mkPackageBuilderFor =
    stdenv': exts: userFn:
    stdenv'.mkDerivation (lib.extends (lib.composeManyExtensions exts) userFn);

  mkPackageBuilder = mkPackageBuilderFor stdenv;

  setVersionLayer = finalAttrs: prevAttrs: {
    preConfigure =
      prevAttrs.preConfigure or ""
      +
      # Update the repo-global .version file.
      # Symlink ./.version points there, but by default only workDir is writable.
      ''
        chmod u+w ./.version
        echo ${finalAttrs.version} > ./.version
      '';
  };

  localSourceLayer =
    finalAttrs: prevAttrs:
    let
      workDirPath =
        # Ideally we'd pick finalAttrs.workDir, but for now `mkDerivation` has
        # the requirement that everything except passthru and meta must be
        # serialized by mkDerivation, which doesn't work for this.
        prevAttrs.workDir;

      workDirSubpath = lib.path.removePrefix root workDirPath;
      sources =
        assert prevAttrs.fileset._type == "fileset";
        prevAttrs.fileset;
      src = lib.fileset.toSource {
        fileset = sources;
        inherit root;
      };

    in
    {
      sourceRoot = "${src.name}/" + workDirSubpath;
      inherit src;

      # Clear what `derivation` can't/shouldn't serialize; see prevAttrs.workDir.
      fileset = null;
      workDir = null;
    };

  resolveRelPath = p: lib.path.removePrefix root p;

  makeFetchedSourceLayer =
    finalScope: finalAttrs: prevAttrs:
    let
      workDirPath =
        # Ideally we'd pick finalAttrs.workDir, but for now `mkDerivation` has
        # the requirement that everything except passthru and meta must be
        # serialized by mkDerivation, which doesn't work for this.
        prevAttrs.workDir;

      workDirSubpath = resolveRelPath workDirPath;

    in
    {
      sourceRoot = "${finalScope.patchedSrc.name}/" + workDirSubpath;
      src = finalScope.patchedSrc;
      version =
        let
          n = lib.length finalScope.patches;
        in
        if n == 0 then prevAttrs.version else prevAttrs.version + "+${toString n}";

      # Clear what `derivation` can't/shouldn't serialize; see prevAttrs.workDir.
      fileset = null;
      workDir = null;
    };

  mesonLayer = finalAttrs: prevAttrs: {
    # NOTE:
    # As of https://github.com/NixOS/nixpkgs/blob/8baf8241cea0c7b30e0b8ae73474cb3de83c1a30/pkgs/by-name/me/meson/setup-hook.sh#L26,
    # `mesonBuildType` defaults to `plain` if not specified. We want our Nix-built binaries to be optimized by default.
    # More on build types here: https://mesonbuild.com/Builtin-options.html#details-for-buildtype.
    mesonBuildType = "release";
    # NOTE:
    # Users who are debugging Nix builds are expected to set the environment variable `mesonBuildType`, per the
    # guidance in https://github.com/NixOS/nix/blob/8a3fc27f1b63a08ac983ee46435a56cf49ebaf4a/doc/manual/source/development/debugging.md?plain=1#L10.
    # For this reason, we don't want to refer to `finalAttrs.mesonBuildType` here, but rather use the environment variable.
    preConfigure =
      prevAttrs.preConfigure or ""
      +
        lib.optionalString
          (
            !(stdenv.hostPlatform.isWindows || stdenv.hostPlatform.isCygwin)
            # build failure
            && !stdenv.hostPlatform.isStatic
          )
          ''
            case "$mesonBuildType" in
            release|minsize) appendToVar mesonFlags "-Db_lto=true"  ;;
            *)               appendToVar mesonFlags "-Db_lto=false" ;;
            esac
          '';
    nativeBuildInputs = [
      meson
      ninja
    ]
    ++ prevAttrs.nativeBuildInputs or [ ];
    mesonFlags =
      prevAttrs.mesonFlags or [ ]
      ++ (lib.optionals scope.withUnityBuild [
        "-Dunity=on"
        "-Dunity_size=8192"
        "-Db_pch=false"
      ]);
    mesonCheckFlags = prevAttrs.mesonCheckFlags or [ ] ++ [
      "--print-errorlogs"
    ];
  };

  mesonBuildLayer = finalAttrs: prevAttrs: rec {
    nativeBuildInputs = prevAttrs.nativeBuildInputs or [ ] ++ [
      pkg-config
    ];
    separateDebugInfo = !stdenv.hostPlatform.isStatic;
    # needed by separateDebugInfo
    # SEE: https://github.com/NixOS/nixpkgs/pull/394674/commits/a4d355342976e9e9823fb94f133bc43ebec9da5b
    __structuredAttrs = separateDebugInfo;
  };

  mesonLibraryLayer = finalAttrs: prevAttrs: {
    preConfigure =
      let
        interpositionFlags = [
          "-fno-semantic-interposition"
          "-Wl,-Bsymbolic-functions"
        ];
      in
      # NOTE: By default GCC disables interprocedular optimizations (in particular inlining) for
      # position-independent code and thus shared libraries.
      # Since LD_PRELOAD tricks aren't worth losing out on optimizations, we disable it for good.
      # This is not the case for Clang, where inlining is done by default even without -fno-semantic-interposition.
      # https://reviews.llvm.org/D102453
      # https://fedoraproject.org/wiki/Changes/PythonNoSemanticInterpositionSpeedup
      prevAttrs.preConfigure or ""
      + lib.optionalString stdenv.cc.isGNU ''
        export CFLAGS="''${CFLAGS:-} ${toString interpositionFlags}"
        export CXXFLAGS="''${CXXFLAGS:-} ${toString interpositionFlags}"
      '';
    outputs = prevAttrs.outputs or [ "out" ] ++ [ "dev" ];
  };

  fixupStaticLayer = finalAttrs: prevAttrs: {
    postFixup =
      prevAttrs.postFixup or ""
      + lib.optionalString (stdenv.hostPlatform.isStatic) ''
        # HACK: Otherwise the result will have the entire buildInputs closure
        # injected by the pkgsStatic stdenv
        # <https://github.com/NixOS/nixpkgs/issues/83667>
        rm -f $out/nix-support/propagated-build-inputs
      '';
  };

  # Work around weird `--as-needed` linker behavior with BSD, see
  # https://github.com/mesonbuild/meson/issues/3593
  bsdNoLinkAsNeeded =
    finalAttrs: prevAttrs:
    lib.optionalAttrs stdenv.hostPlatform.isBSD {
      mesonFlags = [ (lib.mesonBool "b_asneeded" false) ] ++ prevAttrs.mesonFlags or [ ];
    };

  enableSanitizersLayer =
    finalAttrs: prevAttrs:
    let
      sanitizers =
        lib.optional scope.withASan "address"
        ++ lib.optional scope.withUBSan "undefined"
        ++ lib.optional scope.withTSan "thread"
        ++ lib.optional scope.withFuzzer "fuzzer-no-link";
    in
    # Thread sanitizer can't be used with ASan or UBSan
    assert scope.withTSan -> !(scope.withASan || scope.withUBSan);
    {
      mesonFlags =
        (prevAttrs.mesonFlags or [ ])
        ++ lib.optionals (lib.length sanitizers > 0) (
          [
            (lib.mesonOption "b_sanitize" (lib.concatStringsSep "," sanitizers))
          ]
          ++ (lib.optionals stdenv.cc.isClang [
            # https://www.github.com/mesonbuild/meson/issues/764
            (lib.mesonBool "b_lundef" false)
          ])
        );
    };

  enableClangTidyLayer =
    finalAttrs: prevAttrs:
    lib.optionalAttrs scope.withClangTidy {
